CREATE TABLE `coms` (
  `id` int NOT NULL AUTO_INCREMENT,
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `date_created` datetime DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `active` varchar(1) NOT NULL DEFAULT 'Y',
  `drawid` int DEFAULT NULL,
  `agent_id` int DEFAULT NULL,
  `description` text,
  `com_rate` decimal(10,2) NOT NULL DEFAULT '0.00',
  `player_id` int NOT NULL,
  `eventid` int NOT NULL,
  `date_converted` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_coms` (`id`,`date_created`,`user_id`,`active`,`drawid`,`agent_id`,`eventid`,`date_converted`),
  KEY `index_coms` (`id`,`date_created`,`user_id`,`active`,`drawid`,`agent_id`,`eventid`,`date_converted`)
) ENGINE=InnoDB AUTO_INCREMENT=76264 DEFAULT CHARSET=utf8mb3;
